import xml.etree.ElementTree as ET

NS = {
    'bpmn':   'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
    'dc':     'http://www.omg.org/spec/DD/20100524/DC',
    'di':     'http://www.omg.org/spec/DD/20100524/DI',
}

tree = ET.parse('/work/output/artifacts/skill-bpmn-expr-multiinstance-iterator/MultiInstanceIteratorBpmn/MultiInstanceIteratorBpmn.bpmn')
root = tree.getroot()

errors = []
warnings = []

# 1. Root element check
tag = root.tag
if 'definitions' not in tag.lower():
    errors.append(f"Root is not definitions: {tag}")
else:
    print(f"[OK] Root is definitions: {tag}")

# Check required namespaces
attribs = root.attrib
ns_uipath = any('uipath' in v for k,v in attribs.items() if k.startswith('xmlns'))
ns_bpmn   = any('BPMN/20100524/MODEL' in v for k,v in attribs.items() if k.startswith('xmlns'))
print(f"[OK] BPMN namespace present: {ns_bpmn}")
print(f"[OK] uipath namespace present: {ns_uipath}")

# 2. Collect all declared IDs in the process
process = root.find('bpmn:process', NS)
if process is None:
    errors.append("No bpmn:process found")
else:
    print("[OK] bpmn:process found id=" + process.get('id'))

# Collect all element IDs recursively
all_ids = set()
def collect_ids(elem):
    eid = elem.get('id')
    if eid:
        all_ids.add(eid)
    for child in elem:
        collect_ids(child)
collect_ids(root)
print(f"[OK] Total IDs collected: {len(all_ids)}")
print(f"     IDs: {sorted(all_ids)}")

# 3. Check BPMNDiagram exists
diagram = root.find('bpmndi:BPMNDiagram', NS)
if diagram is None:
    errors.append("No BPMNDiagram found")
else:
    print("[OK] BPMNDiagram found")

# Collect all shapes and edges
shapes = {}
edges = {}
plane = root.find('.//bpmndi:BPMNPlane', NS)
if plane is not None:
    for shape in plane.findall('bpmndi:BPMNShape', NS):
        ref = shape.get('bpmnElement')
        shapes[ref] = shape
    for edge in plane.findall('bpmndi:BPMNEdge', NS):
        ref = edge.get('bpmnElement')
        edges[ref] = edge

print(f"[OK] BPMNShape refs: {sorted(shapes.keys())}")
print(f"[OK] BPMNEdge refs:  {sorted(edges.keys())}")

# Check all flow nodes have a shape
flow_nodes = ['Start_1','Sub_MultiInstance','Sub_Start','Task_MapItem','Task_MapIndex','Sub_End','End_1']
for nid in flow_nodes:
    if nid not in shapes:
        errors.append(f"MISSING SHAPE for node {nid}")
    else:
        print(f"[OK] Shape exists for {nid}")

# Check all flows have an edge
flow_ids = ['Flow_StartToSub','Flow_SubStart_MapItem','Flow_MapItem_MapIndex','Flow_MapIndex_SubEnd','Flow_SubToEnd']
for fid in flow_ids:
    if fid not in edges:
        errors.append(f"MISSING EDGE for flow {fid}")
    else:
        print(f"[OK] Edge exists for {fid}")

# 3b. Check every BPMNEdge/BPMNShape bpmnElement ref resolves
for ref in list(shapes.keys()) + list(edges.keys()):
    if ref not in all_ids:
        errors.append(f"BPMNDiagram ref '{ref}' not in declared IDs")
    else:
        print(f"[OK] Diagram ref '{ref}' resolves")

# 4. Check sequence flow sourceRef/targetRef
for sf in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow'):
    sf_id = sf.get('id')
    src = sf.get('sourceRef')
    tgt = sf.get('targetRef')
    if src not in all_ids:
        errors.append(f"Flow {sf_id} sourceRef '{src}' not found")
    if tgt not in all_ids:
        errors.append(f"Flow {sf_id} targetRef '{tgt}' not found")
    print(f"[OK] Flow {sf_id}: {src} -> {tgt}")

# 5. Check gateways: no exclusive gateways with single in/out
for gw in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}exclusiveGateway'):
    inc = gw.findall('bpmn:incoming', NS)
    out = gw.findall('bpmn:outgoing', NS)
    if len(inc) <= 1 and len(out) <= 1:
        errors.append(f"SUPERFLUOUS_GATEWAY: {gw.get('id')} has {len(inc)} incoming and {len(out)} outgoing")
print("[OK] No exclusive gateways (none in this process)")

# 6. Check event subprocesses have exactly one start event with an event definition
# (none here)
print("[OK] No event subprocesses to check")

# 7. Check no double-hyphen in comments
import re
with open('/work/output/artifacts/skill-bpmn-expr-multiinstance-iterator/MultiInstanceIteratorBpmn/MultiInstanceIteratorBpmn.bpmn') as f:
    raw = f.read()
for m in re.finditer(r'<!--(.*?)-->', raw, re.DOTALL):
    if '--' in m.group(1):
        errors.append(f"Double-hyphen in XML comment: {m.group(0)[:60]}")
print("[OK] No double-hyphens in XML comments")

# 8. Check uipath:type child pattern on activities
for task in root.iter():
    if task.tag in (
        '{http://uipath.org/schema/bpmn}activity',
        '{http://uipath.org/schema/bpmn}event',
        '{http://uipath.org/schema/bpmn}mapping',
    ):
        type_child = task.find('{http://uipath.org/schema/bpmn}type')
        if type_child is None:
            errors.append(f"uipath wrapper {task.tag} missing <uipath:type> child")
        else:
            print(f"[OK] uipath wrapper has type child: value={type_child.get('value')}")

# 9. loopCharacteristics check
lc = root.find('.//bpmn:multiInstanceLoopCharacteristics', NS)
if lc is None:
    errors.append("No multiInstanceLoopCharacteristics found")
else:
    print(f"[OK] multiInstanceLoopCharacteristics found, isSequential={lc.get('isSequential')}")
    ulc = lc.find('.//uipath:loopCharacteristics', NS)
    if ulc is None:
        errors.append("Missing uipath:loopCharacteristics inside multiInstanceLoopCharacteristics")
    else:
        ic = ulc.get('inputCollection')
        ie = ulc.get('inputElement')
        print(f"[OK] uipath:loopCharacteristics: inputCollection={ic}, inputElement={ie}")
        if ic != '=vars.Var_Items':
            errors.append(f"inputCollection should be '=vars.Var_Items', got '{ic}'")
        if ie != 'iterator[0]':
            errors.append(f"inputElement should be 'iterator[0]', got '{ie}'")

# 10. Check iterator[0].item and iterator[0].loopCounter appear in script inputs
found_item = False
found_counter = False
for inp in root.iter('{http://uipath.org/schema/bpmn}input'):
    body = inp.text or ''
    if 'iterator[0].item' in body:
        found_item = True
    if 'iterator[0].loopCounter' in body:
        found_counter = True
if not found_item:
    errors.append("iterator[0].item not found in any uipath:input")
else:
    print("[OK] iterator[0].item found in uipath:input")
if not found_counter:
    errors.append("iterator[0].loopCounter not found in any uipath:input")
else:
    print("[OK] iterator[0].loopCounter found in uipath:input")

# 11. Check output var references resolve to declared variable IDs
var_ids = set()
for v in root.iter():
    if v.tag in (
        '{http://uipath.org/schema/bpmn}input',
        '{http://uipath.org/schema/bpmn}output',
        '{http://uipath.org/schema/bpmn}inputOutput',
    ):
        vid = v.get('id')
        if vid:
            var_ids.add(vid)
print(f"[OK] Declared variable IDs: {sorted(var_ids)}")

for out in root.iter('{http://uipath.org/schema/bpmn}output'):
    vref = out.get('var')
    if vref and vref not in var_ids:
        errors.append(f"uipath:output var='{vref}' not in declared variable IDs")
    elif vref:
        print(f"[OK] uipath:output var='{vref}' resolves")

# Summary
print()
if errors:
    print(f"ERRORS ({len(errors)}):")
    for e in errors:
        print(f"  ERROR: {e}")
else:
    print("STRUCTURAL CHECKLIST: ALL CHECKS PASSED")

PYEOF

